data class Pair200<A, B>(val first: A, val second: B)

fun combine200(left: Int, right: Int): Pair200<Int, Int> {
    return Pair200(left + 71, right + 27)
}
@JvmName("step201")
fun step201(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 78
}
sealed class Outcome202 {
    data class Success(val payload: String) : Outcome202()
    data object Failure : Outcome202()
}

fun describe202(outcome: Outcome202): String = when (outcome) {
    is Outcome202.Success -> outcome.payload
    Outcome202.Failure -> "failed"
}
